import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
def load():
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def transform(g):
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    out=[r[:] for r in g]
    import sys; sys.setrecursionlimit(10000)
    def flood(i,j,c):
        stack=[(i,j)]; cells=[]
        while stack:
            a,b=stack.pop()
            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==c:
                seen[a][b]=True; cells.append((a,b))
                stack+= [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
        return cells
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; cells=flood(i,j,c)
                rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                iw=c1-c0-1; ih=r1-r0-1
                fill=7 if iw%2==1 else 2
                for a in range(r0+1,r1):
                    for b in range(c0+1,c1):
                        if g[a][b]==bg: out[a][b]=fill
    return out
